import { useState } from "react";
import axios from "axios";

function App() {
  const [query, setQuery] = useState("");        // what user types
  const [results, setResults] = useState([]);    // 5 topic suggestions

  // Fetch from Wikipedia API
  const handleSearch = async () => {
    if (!query) return;
    try {
      const res = await axios.get(
        `https://en.wikipedia.org/w/api.php`,
        {
          params: {
            action: "opensearch",
            search: query,
            limit: 5,
            namespace: 0,
            format: "json",
            origin: "*",  // allows cross-origin request
          },
        }
      );
      setResults(res.data[1]); // array of topic titles
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div style={{ padding: 40 }}>
      <h1>Deep Dive</h1>

      {/* Search Bar */}
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Type a topic..."
        style={{ padding: 8, width: 300, marginRight: 8 }}
      />
      <button onClick={handleSearch} style={{ padding: 8 }}>
        Search
      </button>

      {/* Show 5 topics */}
      <ul style={{ marginTop: 20 }}>
        {results.map((topic) => (
          <li key={topic}>
            <a
              href={`https://en.wikipedia.org/wiki/${encodeURIComponent(topic)}`}
              target="_blank"
              rel="noopener noreferrer"
            >
              {topic}
            </a>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
